<?php
declare(strict_types=1);
require __DIR__.'/../config/app.php'; require __DIR__.'/../includes/staff-layout.php';
$staff=at_staff();
if(!in_array($staff['role'],['Staff','Manager'],true)){http_response_code(403);exit('Staff or Manager permission required.');}
$pdo=at_db();$error='';$flash=at_flash();
try{if($_SERVER['REQUEST_METHOD']==='POST'){at_check_csrf();$action=(string)($_POST['action']??'');$pdo->beginTransaction();
 if($action==='create'){
  $customerId=at_int($_POST['customer_id']??null);$productId=at_int($_POST['product_id']??null);$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>1000]])?:0;
  if(!$customerId||!$productId||!$qty)throw new RuntimeException('Select a customer, item, and quantity from 1 to 1000.');
  $q=$pdo->prepare("SELECT customer_id FROM customers WHERE customer_id=? AND status='Active'");$q->execute([$customerId]);if(!$q->fetch())throw new RuntimeException('Select an active customer.');
  $q=$pdo->prepare("SELECT unit_price FROM products WHERE product_id=? AND status='Active'");$q->execute([$productId]);$price=$q->fetchColumn();if($price===false)throw new RuntimeException('Select an active sellable item.');
  $unit=at_money_cents((string)$price);$total=$unit*$qty;$q=$pdo->prepare("INSERT INTO orders(customer_id,order_date,total_amount,order_status,created_by,created_at,updated_at) VALUES (?,NOW(),?,'Pending',?,NOW(),NOW())");$q->execute([$customerId,at_decimal($total),$staff['user_id']]);$id=(int)$pdo->lastInsertId();
  $q=$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price,subtotal,created_at,updated_at) VALUES (?,?,?,?,?,NOW(),NOW())');$q->execute([$id,$productId,$qty,at_decimal($unit),at_decimal($total)]);at_log($pdo,(int)$staff['user_id'],'Staff created order','orders',$id);$message='Order created.';
 }elseif($action==='status'){
  $id=at_int($_POST['order_id']??null);$next=(string)($_POST['status']??'');$q=$pdo->prepare('SELECT order_status FROM orders WHERE order_id=? AND created_by=? FOR UPDATE');$q->execute([$id,$staff['user_id']]);$old=$q->fetchColumn();if(!($old==='Pending'&&$next==='Confirmed')&&!($old==='Confirmed'&&$next==='Preparing'))throw new RuntimeException('Only your pending or confirmed orders can be advanced.');$pdo->prepare('UPDATE orders SET order_status=?,updated_at=NOW() WHERE order_id=?')->execute([$next,$id]);at_log($pdo,(int)$staff['user_id'],'Staff order status: '.$next,'orders',$id);$message='Order updated.';
 }else throw new RuntimeException('Invalid order action.');$pdo->commit();at_flash($message);at_redirect('orders.php');}}
catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=at_failure($e,'staff-orders');}
$customers=$pdo->query("SELECT customer_id,customer_name FROM customers WHERE status='Active' ORDER BY customer_name")->fetchAll();$products=$pdo->query("SELECT product_id,product_name,unit_price FROM products WHERE status='Active' ORDER BY product_name")->fetchAll();$q=$pdo->prepare('SELECT o.*,c.customer_name FROM orders o JOIN customers c ON c.customer_id=o.customer_id WHERE o.created_by=? ORDER BY o.order_id DESC LIMIT 120');$q->execute([$staff['user_id']]);$orders=$q->fetchAll();
at_staff_open('My Orders','orders',$staff,'Create and process orders recorded under your account.');
if($flash):?><div class="op-notice" role="status"><?=at_h($flash)?></div><?php endif;if($error):?><div class="op-notice bad" role="alert"><?=at_h($error)?></div><?php endif;?>
<div class="op-grid"><section class="op-card"><h2>New order</h2><p class="op-description">One item per order. Prices are verified from active sellable items.</p><?php if(!$customers||!$products):?><p class="op-hint">An administrator must add an active customer and sellable item first.</p><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=at_h(at_csrf())?>"><input type="hidden" name="action" value="create"><label class="op-field">Customer<select name="customer_id" required><option value="">Select customer</option><?php foreach($customers as $c):?><option value="<?=$c['customer_id']?>"><?=at_h($c['customer_name'])?></option><?php endforeach;?></select></label><label class="op-field">Item<select name="product_id" required><option value="">Choose item</option><?php foreach($products as $p):?><option value="<?=$p['product_id']?>"><?=at_h($p['product_name'])?> — <?=at_peso($p['unit_price'])?></option><?php endforeach;?></select></label><label class="op-field">Quantity<input name="quantity" type="number" min="1" max="1000" value="1" required></label><button type="submit" class="op-button">Save Order</button></form><?php endif;?></section><section class="op-card"><h2>My order records</h2><p class="op-description">Only your own orders can be advanced here.</p><div class="op-table-wrap"><table class="op-table"><thead><tr><th>Order</th><th>Customer</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['order_id']?> — <?=at_h($o['order_date'])?></td><td><?=at_h($o['customer_name'])?></td><td><?=at_peso($o['total_amount'])?></td><td><span class="op-pill"><?=at_h($o['order_status'])?></span></td><td><?php $next=match($o['order_status']){'Pending'=>'Confirmed','Confirmed'=>'Preparing',default=>null};if($next):?><form class="op-inline-form" method="post"><input type="hidden" name="csrf_token" value="<?=at_h(at_csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="order_id" value="<?=$o['order_id']?>"><input type="hidden" name="status" value="<?=$next?>"><button type="submit">Mark <?=at_h($next)?></button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="5">No orders created by this account yet.</td></tr><?php endif;?></tbody></table></div></section></div>
<?php at_staff_close();
